SELECT percent_rank() OVER (ORDER BY AVG(labevents.value)) AS percentile_rank FROM icustays JOIN labevents ON icustays.stay_id = labevents.subject_id WHERE icustays.subject_id = 88 AND icustays.gender = 1 AND icustays.first_careunit = 'ICU' AND EXTRACT(YEAR FROM icustays.intime) = 2017 AND EXTRACT(YEAR FROM icustays.outtime) = 2017 AND labevents.itemid = 171 AND labevents.value >= 60 AND labevents.value <= 100 AND labevents.charttime BETWEEN icustays.intime AND icustays.outtime GROUP BY icustays.stay_id HAVING COUNT(labevents.labevent_id) >= 3;